import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, analysis, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    target_length = float(int(ctx.index) % 3 + 1)
    return {"inputs": synth.Tensor(inputs), "target_length": synth.Tensor(torch.tensor(target_length))}
dataset = synth.Spec("cif-quantity", generator=samples, size=12, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class CIFPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=3)
    def forward(self, inputs):
        return {"alpha": self.network(inputs).sigmoid()}
model = CIFPredictor()
trainer = Trainer(model, train, recipe="structured-objective", recipe_config={"loss": "cif-quantity", "bindings": {"logits_or_prediction": {"output": "alpha"}, "targets": {"batch": "target_length"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
report = analysis.analyze(model)
